/*
 * Road racer, stage 1: pseudo-3D road with speed, steering and heading,
 * distant mountains, a speed bar and engine sound.
 *
 * Inputs : ui_in[0] left, ui_in[1] right, ui_in[2] accelerate, ui_in[3] brake
 * Outputs: uo_out = Tiny VGA PMOD (RGB222 + syncs)
 *          uio[0] = audio (PWM, needs an RC filter on real hardware)
 *
 * Rename the module to tt_um_<your GitHub username>_... before pushing.
 */

module tt_um_yamin_d_first_person_driving_game #(
    parameter WHEEL_FULL = 1        // 0: small wheel for 1x1, 1: full wheel for 1x2
) (
    input  wire [7:0] ui_in,
    output wire [7:0] uo_out,
    input  wire [7:0] uio_in,
    output wire [7:0] uio_out,
    output wire [7:0] uio_oe,
    input  wire       ena,
    input  wire       clk,
    input  wire       rst_n
);
    // ---- reset, registered once: the input pin arrives late in the clock and
    // fans out to about a hundred registers, so the inside uses a flip-flop
    reg rst_q;
    always @(posedge clk)
        rst_q <= rst_n;

    // ---- timing
    wire [9:0] x, y;
    wire hsync, vsync, active, frame, line_end;
    vga_timing vga (
        .clk(clk), .rst_n(rst_q), .x(x), .y(y),
        .hsync(hsync), .vsync(vsync), .active(active), .frame(frame),
        .line_end(line_end)
    );

    // ---- buttons
    wire [3:0] btn;
    ip_input_sync #(.N(4)) sync (.clk(clk), .in(ui_in[3:0]), .out(btn));

    // ---- car state, once per frame
    wire        [7:0] v;
    wire signed [2:0] wheel;
    wire signed [7:0] h;
    wire signed [7:0] p;
    wire        [8:0] D;
    wire              offroad;
    wire signed [3:0] kappa;
    wire       [11:0] slow, onc;
    wire              clr_slow, clr_onc;
    wire              flash;
    wire        [3:0] tens, ones;
    car_state car (
        .clk(clk), .rst_n(rst_q), .frame(frame),
        .left(btn[0]), .right(btn[1]), .accel(btn[2]), .brake(btn[3]),
        .v(v), .wheel(wheel), .h(h), .p(p), .D(D), .offroad(offroad), .kappa(kappa),
        .slow(slow), .onc(onc), .clr_slow(clr_slow), .clr_onc(clr_onc), .flash(flash),
        .tens(tens), .ones(ones)
    );

    // ---- per-line values
    wire        [10:0] z;
    wire signed [10:0] Ae;
    wire        [10:0] zs;
    wire               z_latch;
    line_setup #(.Z_BITS(11)) line (
        .clk(clk), .rst_n(rst_q), .x(x), .y(y), .h(h), .p(p),
        .kappa(kappa), .z(z), .Ae(Ae), .zs(zs), .latch(z_latch)
    );

    // ---- per-pixel colour
    wire [5:0] rgb;
    pixel_colour #(.WHEEL_FULL(WHEEL_FULL)) pix (
        .clk(clk), .rst_n(rst_q), .x(x), .y(y), .active(active), .z(z[3:0]), .Ae(Ae), .h(h),
        .d_hi(D[8:5]), .wheel(wheel), .v(v), .zs(zs), .latch(z_latch),
        .zc_slow(slow[11:1]), .zc_onc(onc[11:1]), .clr_slow(clr_slow), .clr_onc(clr_onc),
        .flash(flash), .kappa(kappa), .tens(tens), .ones(ones), .rgb(rgb)
    );

    // ---- sound
    wire [7:0] sample;
    wire       audio;
    engine_audio engine (
        .clk(clk), .rst_n(rst_q), .tick(line_end), .v(v),
        .offroad(offroad | flash), .pwm_count(x[7:0]), .sample(sample), .out(audio)
    );

    // ---- outputs, registered so every pin changes on the same clock edge.
    // pixel_colour has one pipeline stage, so the syncs are delayed one clock
    // to stay lined up with the colour.
    // Tiny VGA PMOD order: {hsync, B0, G0, R0, vsync, B1, G1, R1}
    reg hsync_q, vsync_q;
    reg [7:0] vga_out;
    always @(posedge clk) begin
        hsync_q <= hsync;
        vsync_q <= vsync;
        vga_out <= {hsync_q, rgb[0], rgb[2], rgb[4], vsync_q, rgb[1], rgb[3], rgb[5]};
    end

    assign uo_out  = vga_out;
    assign uio_out = {7'b0000000, audio};
    assign uio_oe  = 8'b0000_0001;

    wire _unused = &{ena, uio_in, ui_in[7:4], D[4:0], z[10:4], slow[0], onc[0], frame, sample, 1'b0};
endmodule

// ==========================================================================
// vga_timing.v
// ==========================================================================
// 640x480 at 60 Hz from a 25 MHz clock: 800 clocks per line, 525 lines per frame.
// x and y count every clock, including blanking, so other blocks can schedule
// work at fixed positions (x = 640 starts horizontal blanking, y = 480 vertical).

module vga_timing (
    input  wire       clk,
    input  wire       rst_n,
    output reg  [9:0] x,        // 0..799
    output reg  [9:0] y,        // 0..524
    output wire       hsync,    // active low
    output wire       vsync,    // active low
    output wire       active,   // high inside the 640x480 picture
    output reg        frame,    // one-clock pulse at the start of vertical blanking
    output reg        line_end  // one-clock pulse at x = 799 on every line
);
    always @(posedge clk) begin
        if (!rst_n) begin
            x <= 10'd0;
            y <= 10'd0;
        end else if (x == 10'd799) begin
            x <= 10'd0;
            y <= (y == 10'd524) ? 10'd0 : y + 10'd1;
        end else begin
            x <= x + 10'd1;
        end
    end

    assign hsync  = ~((x >= 10'd656) && (x < 10'd752));
    assign vsync  = ~((y >= 10'd490) && (y < 10'd492));
    assign active = (x < 10'd640) && (y < 10'd480);
    // registered strobes, decoded one clock early (see line_setup)
    always @(posedge clk) begin
        frame    <= (x == 10'd799) && (y == 10'd479);   // high at x = 0, y = 480
        line_end <= (x == 10'd798);                     // high at x = 799
    end
endmodule

// ==========================================================================
// ip_input_sync.v
// ==========================================================================
// Two-flop synchroniser for the buttons. There is no debounce counter:
// car_state only reads the buttons on the frame pulse, every 16.7 ms, which is
// longer than a switch bounces, so each read sees either the old or new state.

module ip_input_sync #(
    parameter N = 4
) (
    input  wire         clk,
    input  wire [N-1:0] in,
    output wire [N-1:0] out
);
    reg [N-1:0] s1, s2;
    always @(posedge clk) begin
        s1 <= in;
        s2 <= s1;
    end
    assign out = s2;
endmodule

// ==========================================================================
// car_state.v
// ==========================================================================
// Car state, updated once per frame on the frame pulse.
//   v      speed, 0..192
//   wheel  wheel angle, -2..2, centres itself when no steering button is held
//   h      heading in pixels (f * psi), stops growing past +/-96
//   P      sideways position with 6 fraction bits; p = P >>> 6, road edge at |p| = 64,
//          stops moving outwards past |p| = 96
//   D      distance travelled, 9 bits, wraps (only its top bits are used)
//   track  counts D wrapping; its top 4 bits are the track segment
//   kappa  road curvature, moves one step towards the segment's value per wrap
//   slow, onc  depths of the slow and oncoming cars, 1 fraction bit, one shared adder
//   crash  frames left of the crash stop; tens, ones  score, cars overtaken
// Matches Car.frame() in road_model.py.

module car_state (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              frame,
    input  wire              left,
    input  wire              right,
    input  wire              accel,
    input  wire              brake,
    output reg         [7:0] v,
    output reg  signed [2:0] wheel,
    output reg  signed [7:0] h,
    output wire signed [7:0] p,
    output reg         [8:0] D,
    output reg               offroad,
    output reg  signed [3:0] kappa,
    output reg         [11:0] slow,
    output reg         [11:0] onc,
    output reg                clr_slow,   // this car respawned: forget its base row
    output reg                clr_onc,
    output reg                flash,      // crash stop in progress
    output reg         [3:0]  tens,
    output reg         [3:0]  ones
);
    localparam [7:0] V_MAX = 8'd192;

    reg signed [13:0] P;
    reg        [2:0]  n;          // frame counter for coasting drag

    assign p = P[13:6];           // same as P >>> 6
    // |p| >= 72 without working out |p|: compare against constants. Registered:
    // P changes only on step_p, long before the next frame pulse reads it.
    always @(posedge clk)
        offroad <= (p >= 8'sd72) || (p <= -8'sd72);

    // ---- speed: one small signed step, one adder, clamp at zero
    reg signed [3:0] d;
    always @(*) begin
        if (offroad && v > 8'd96) d = brake ? -4'sd4 : -4'sd2;   // grass drag
        else if (accel)           d = (v == V_MAX) ? 4'sd0 : 4'sd1;
        else if (brake)           d = -4'sd4;
        else if (n == 3'd0)       d = -4'sd1;
        else                      d = 4'sd0;
    end
    // The step is registered every clock; its inputs (buttons, v, n, offroad)
    // are all steady before the frame pulse, so the pulse just adds it.
    reg signed [3:0] d_q;
    always @(posedge clk)
        d_q <= d;
    wire signed [8:0] v_sum = $signed({1'b0, v}) + {{5{d_q[3]}}, d_q};
    wire        [7:0] v1    = v_sum[8] ? 8'd0 : v_sum[7:0];

    // ---- wheel angle
    reg signed [2:0] wheel1;
    always @(*) begin
        if (left && !right)       wheel1 = (wheel == -3'sd2) ? -3'sd2 : wheel - 3'sd1;
        else if (right && !left)  wheel1 = (wheel ==  3'sd2) ?  3'sd2 : wheel + 3'sd1;
        else if (wheel[2])        wheel1 = wheel + 3'sd1;
        else if (wheel != 3'sd0)  wheel1 = wheel - 3'sd1;
        else                      wheel1 = 3'sd0;
    end

    // The update is spread over three clocks so each clock has one adder:
    //   frame     speed, wheel and frame counter
    //   step_k    (the speed factor k is registered from the new speed)
    //   step_h    heading, from the registered speed factor and wheel
    //   step_p    position and distance, from the registered heading
    // This gives exactly the same result as doing it all at once, in the same
    // order as road_model.py, and it is all done within 4 clocks of the pulse.
    reg step_k, step_h, step_p, step_s, step_o, step_x;
    reg [5:0] crash;
    wire crashing = (crash != 6'd0);

    // ---- traffic: one adder, slow car on step_s, oncoming car on step_o
    reg                sel_o;                            // a copy of step_o for the data path
    always @(posedge clk)
        sel_o <= step_s;
    wire        [11:0] z_now = sel_o ? onc : slow;
    // registered one clock ahead: v arrives from a heavily loaded net
    reg  signed  [5:0] delta;
    always @(posedge clk)
        delta <= (step_s ? -6'sd4 : 6'sd6) - {2'b00, v[7:4]};
    wire        [12:0] z_sum = {1'b0, z_now} + {{7{delta[5]}}, delta};
    wire               z_under = z_sum[12];              // passed: respawn
    wire               z_hold  = ~delta[5] & (z_now[11:6] == 6'b111111);
    wire         [4:0] rnd   = D[4:0] ^ {track[1:0], n};
    wire        [11:0] far_s = {1'b1,  rnd, 6'd0};
    wire        [11:0] far_o = {1'b1, ~rnd, 6'd0};
    wire        [11:0] z_next = z_hold ? z_now : z_sum[11:0];
    wire near_s = (slow[11:7] == 5'd0);
    wire near_o = (onc[11:7] == 5'd0);
    wire hit = (near_s & ~p[7] & ~p[6]) | (near_o & p[7] & p[6]);
    always @(posedge clk) begin
        flash    <= crashing;
        clr_slow <= (step_s & z_under) | (step_x & hit);
        clr_onc  <= (step_o & z_under) | (step_x & hit);
    end

    // ---- the track: 16 segments of 64 wraps of D (see TRACK in road_model.py)
    reg        [9:0] track;
    reg signed [3:0] target;
    always @(*) begin
        case (track[9:6])
            4'd2, 4'd3:   target =  4'sd5;
            4'd5, 4'd6:   target = -4'sd6;
            4'd8:         target =  4'sd7;
            4'd9:         target = -4'sd8;
            4'd11, 4'd12: target = -4'sd5;
            4'd13:        target =  4'sd6;
            default:      target =  4'sd0;
        endcase
    end
    wire [9:0] D_sum = {1'b0, D} + {2'b00, v};

    // ---- speed factor 0, 1 or 2: multiplying by it is a shift
    reg k1, k2;                   // registered: v changes only on the frame pulse
    always @(posedge clk) begin
        k1 <= v[6] & ~v[7];       // 64 <= v < 128
        k2 <= v[7];               // v >= 128
    end

    // limits: value >= 96 or value <= -97, from the top three bits only
    function at_limit(input [2:0] top, input step_neg, input step_zero);
        at_limit = !step_zero && (step_neg ? (top == 3'b100) : (top == 3'b011));
    endfunction

    // heading: h + wheel*k, held once it passes +/-96
    wire signed [7:0] w8  = {{5{wheel[2]}}, wheel};
    // a hard bend, |kappa| >= 4, pushes the heading outwards
    wire              push  = kappa[2] ^ kappa[3];
    wire signed [7:0] steer = !push ? w8 : kappa[3] ? w8 + 8'sd1 : w8 - 8'sd1;
    wire signed [7:0] dh  = k2 ? (steer <<< 1) : (k1 ? steer : 8'sd0);
    wire              h_stop = at_limit(h[7:5], steer[7], (steer == 8'sd0) || !(k1 || k2));
    wire signed [7:0] h1  = h_stop ? h : h + dh;

    // position: P + h*k, held once |p| passes 96
    wire signed [13:0] h14   = {{6{h[7]}}, h};
    wire signed [13:0] dP    = k2 ? (h14 <<< 1) : (k1 ? h14 : 14'sd0);
    wire               P_stop = at_limit(P[13:11], h[7], (h == 8'sd0) || !(k1 || k2));
    wire signed [13:0] P1    = P_stop ? P : P + dP;

    // Reset reaches about 150 registers here, so it is split into three. They
    // form a chain, because synthesis would merge identical copies into one.
    reg rst_car, rst_traffic, rst_pos;
    always @(posedge clk) begin
        rst_car     <= rst_n;
        rst_pos     <= rst_car;
        rst_traffic <= rst_pos;
    end

    always @(posedge clk) begin
        if (!rst_car) begin
            v      <= 8'd0;
            wheel  <= 3'sd0;
            n      <= 3'd0;
            track  <= 10'd0;
            kappa  <= 4'sd0;
            crash  <= 6'd0;
            step_k <= 1'b0;
            step_h <= 1'b0;
            step_p <= 1'b0;
            step_s <= 1'b0;
            step_o <= 1'b0;
            step_x <= 1'b0;
        end else begin
            step_k <= frame & ~crashing;
            step_h <= step_k;
            step_p <= step_h;
            step_s <= step_p;
            step_o <= step_s;
            step_x <= step_o;
            if (frame) begin
                n <= n + 3'd1;
                if (crashing) begin
                    crash <= crash - 6'd1;
                end else begin
                    v     <= v1;
                    wheel <= wheel1;
                end
            end
            if (step_p) begin
                if (D_sum[9]) begin
                    track <= track + 10'd1;
                    if ((kappa != target) && (track[1:0] == 2'd0))   // eases in
                        kappa <= (kappa < target) ? kappa + 4'sd1 : kappa - 4'sd1;
                end
            end
            if (step_x & hit) begin
                crash <= 6'd63;
                v     <= 8'd0;
                wheel <= 3'sd0;
            end
        end
    end

    always @(posedge clk) begin
        if (!rst_pos) begin
            h <= 8'sd0;
            P <= 14'sd2048;                // right lane
            D <= 9'd0;
        end else begin
            if (step_h)
                h <= h1;
            if (step_p) begin
                P <= P1;
                D <= D_sum[8:0];
            end
            if (step_x & hit) begin
                h <= 8'sd0;
                P <= 14'sd2048;
            end
        end
    end

    // The slow car being passed is registered, so the score counts one clock
    // later and the adder's carry chain does not run on into it.
    reg passed;
    always @(posedge clk)
        passed <= step_s & z_under;

    always @(posedge clk) begin
        if (!rst_traffic) begin
            slow <= 12'd2048;
            onc  <= 12'd2048;
            tens <= 4'd0;
            ones <= 4'd0;
        end else begin
            if (step_s)
                slow <= z_under ? far_s : z_next;
            if (step_o)
                onc <= z_under ? far_o : z_next;
            if (passed) begin
                ones <= (ones == 4'd9) ? 4'd0 : ones + 4'd1;
                if (ones == 4'd9)
                    tens <= (tens == 4'd9) ? 4'd0 : tens + 4'd1;
            end
            if (step_x & hit) begin
                slow <= far_s;
                onc  <= far_o;
                tens <= 4'd0;
                ones <= 4'd0;
            end
        end
    end
endmodule

// ==========================================================================
// line_setup.v
// ==========================================================================
// Per-line values for the road.
//   z  = 2**14 / s_y, from a restoring divider producing one quotient bit per
//        clock. It starts at x = 640 (after the visible pixels) and works out z
//        for the NEXT line in 15 clocks; the quotient register then holds that z
//        for the whole of the next line.
//   A  = ((h - 320) << 6) + p * s_y, within 17 bits. Loaded at the end of the
//        last sky row and then built by adding p once per road row.
//   Ae = (A >>> 6) plus the curve offset kappa * z / 64, for the next line. Built
//        in horizontal blanking with up to three shifted adds, after the divider
//        has finished, so the pixel stage still needs one adder: x - centre = x + Ae.

module line_setup #(
    parameter Z_BITS = 11         // quotient bits kept (11..15); curves use the low 11
) (
    input  wire               clk,
    input  wire               rst_n,
    input  wire        [9:0]  x,
    input  wire        [9:0]  y,
    input  wire signed [7:0]  h,
    input  wire signed [7:0]  p,
    input  wire signed [3:0]  kappa,
    output wire [Z_BITS-1:0]  z,
    output reg  signed [10:0] Ae,
    output wire        [10:0] zs,          // next row's depth, valid when latch is high
    output wire               latch
);
    localparam [9:0] HORIZON  = 10'd128;
    localparam [9:0] ROAD_END = 10'd384;     // the dashboard is drawn over the last rows

    // ---- divider: s_y of the next line is y + 1 - 128 = y - 127 (1..255)
    // divisor for the next line, registered: y is steady for 640 clocks first
    reg  [7:0] d;
    always @(posedge clk)
        d <= y[7:0] - 8'd127;                           // same as (y - 127) mod 256

    // Strobes are decoded one clock early and registered, so each comes
    // straight from a flip-flop on the same cycle as before. This keeps the
    // decode logic off the paths into the many registers they control.
    reg start;                    // high at x = 640 on rows 128..382
    reg a_load;                   // high at x = 640 on row 127
    reg a_add;                    // high at x = 640 on rows 128..383
    reg z_ready;                  // high at x = 656, once z is ready
    reg e_load;                   // high at x = 658, after the old Ae has been used
    reg e_step;                   // high at x = 660..662
    reg [1:0] e_bit;              // 0, 1, 2 at x = 659..661, one clock before e_step
    always @(posedge clk) begin
        start  <= (x == 10'd639) && (y >= HORIZON) && (y < ROAD_END - 10'd1);
        a_load <= (x == 10'd639) && (y == HORIZON - 10'd1);
        a_add  <= (x == 10'd639) && (y >= HORIZON) && (y < ROAD_END);
        z_ready <= (x == 10'd655);
        e_load <= (x == 10'd657);
        e_step <= (x >= 10'd659) && (x < 10'd662);
        e_bit  <= x[1:0] + 2'd2;
    end

    reg [7:0]  r;                 // remainder, always < d after a step
    reg [Z_BITS-1:0] q;           // the last Z_BITS quotient bits are the low bits
    reg [3:0]  i;                 // 14..0 while dividing, 15 when idle

    wire       busy = (i != 4'd15);
    wire [8:0] r_sh = {r, (i == 4'd14)};               // bring down the next bit of 2**14
    wire [9:0] diff = {1'b0, r_sh} - {2'b00, d};       // one subtractor ...
    wire       ge   = ~diff[9];                        // ... whose borrow is the compare
    wire [7:0] r_new = ge ? diff[7:0] : r_sh[7:0];

    always @(posedge clk) begin
        if (!rst_n)      i <= 4'd15;
        else if (start)  i <= 4'd14;
        else if (busy)   i <= i - 4'd1;                 // 0 -> 15 ends the run
    end

    // r and q need no reset: r is cleared at start and q is fully shifted over
    always @(posedge clk) begin
        if (start) begin
            r <= 8'd0;
        end else if (busy) begin
            r <= r_new;
            q <= {q[Z_BITS-2:0], ge};
        end
    end

    assign z = q;

    // ---- centre offset and steering accumulator
    wire signed [10:0] h_off = {{3{h[7]}}, h} - 11'sd320;
    // no reset: A is always loaded on row 127, before any road row
    reg signed [16:0] A;
    always @(posedge clk) begin
        if (a_load)
            A <= {h_off, 6'b000000};
        else if (a_add)
            A <= A + {{9{p[7]}}, p};
    end

    // ---- curve: Ae = (A >>> 6) -/+ (kappa * z >> 6), one shifted add per clock.
    // Negative kappa's magnitude is its bit inversion; subtraction is one's
    // complement, so no carry in. z is clamped very near the horizon (s_y < 9).
    wire        sat  = (d[7:4] == 4'd0) & (~d[3] | (d[2:0] == 3'd0));
    assign zs    = sat ? 11'd2047 : q[10:0];
    assign latch = z_ready;
    wire [2:0]  mag  = kappa[2:0] ^ {3{kappa[3]}};
    wire [10:0] term = (e_bit == 2'd0) ? {6'd0, zs[10:6]} :
                       (e_bit == 2'd1) ? {5'd0, zs[10:5]} : {4'd0, zs[10:4]};
    wire        use_bit = (e_bit == 2'd0) ? mag[0] :
                          (e_bit == 2'd1) ? mag[1] : mag[2];
    // The shifted term is registered first, so the adder starts from flip-flops:
    // kappa arrives from far away, and the carry chain alone is a long path.
    reg [10:0] term_q;
    reg        use_q;
    always @(posedge clk) begin
        term_q <= term ^ {11{~kappa[3]}};
        use_q  <= use_bit;
    end
    // no reset: loaded on every line
    always @(posedge clk) begin
        if (e_load)
            Ae <= A[16:6];
        else if (e_step & use_q)
            Ae <= Ae + term_q;
    end
    wire _unused = &{diff[8], A[5:0], 1'b0};
endmodule

// ==========================================================================
// pixel_colour.v
// ==========================================================================
// Colour of the pixel at (x, y), in two pipeline stages so that each clock
// has only part of the work (the slow corner of GF180 needs this):
//   stage 1  |x - centre|, the mountain test and the speed-bar test, registered
//   stage 2  compare against the road widths and choose the colour
// rgb therefore belongs to the pixel one clock earlier than (x, y); the top
// level delays the syncs by the same clock. Per pixel there are only small
// adders, comparators and multiplexers. rgb is {R1,R0,G1,G0,B1,B0}.
// Layout: sky 0-127, horizon 128, road 129-351, dashboard 352-479, chosen so
// that s_y and the region tests are bit slices of y.

module pixel_colour #(parameter WHEEL_FULL = 0) (
    input  wire               clk,
    input  wire               rst_n,
    input  wire        [9:0]  x,
    input  wire        [9:0]  y,
    input  wire               active,
    input  wire        [3:0]  z,       // low bits of this line's depth, from line_setup
    input  wire signed [10:0] Ae,      // x - centre = x + Ae, set in blanking
    input  wire signed [7:0]  h,       // heading in pixels
    input  wire        [3:0]  d_hi,    // distance >> 5
    input  wire signed [2:0]  wheel,   // wheel angle, -2..2
    input  wire        [7:0]  v,       // speed, for the digits
    input  wire        [10:0] zs,      // next row's depth (with latch)
    input  wire               latch,
    input  wire        [10:0] zc_slow, // depth of each car
    input  wire        [10:0] zc_onc,
    input  wire               clr_slow,// a car respawned
    input  wire               clr_onc,
    input  wire               flash,   // crash stop
    input  wire signed [3:0]  kappa,   // road curvature
    input  wire        [3:0]  tens,    // score
    input  wire        [3:0]  ones,
    output reg         [5:0]  rgb
);
    // colours, RR_GG_BB
    localparam [5:0] SKY0     = 6'b00_00_01;   // a sunset
    localparam [5:0] SKY1     = 6'b01_00_10;
    localparam [5:0] SKY2     = 6'b11_01_01;
    localparam [5:0] SKY3     = 6'b11_10_00;
    localparam [5:0] SKY4     = 6'b11_11_01;
    localparam [5:0] MOUNTAIN = 6'b01_00_01;
    localparam [5:0] DASH_COL = 6'b01_01_01;
    localparam [5:0] COCKPIT  = 6'b00_00_01;
    localparam [5:0] MIRROR   = 6'b10_10_10;
    localparam [5:0] VENT_COL = 6'b10_10_10;
    localparam [5:0] SLOW_BODY = 6'b00_01_11;
    localparam [5:0] SLOW_LAMP = 6'b11_00_00;
    localparam [5:0] ONC_BODY  = 6'b11_11_11;
    localparam [5:0] ONC_LAMP  = 6'b11_11_00;
    localparam [5:0] SLOW_SIDE = 6'b00_00_10;
    localparam [5:0] ONC_SIDE  = 6'b10_10_10;
    localparam [5:0] PANEL_COL = 6'b00_00_00;
    localparam [5:0] BAR_COL  = 6'b11_10_00;
    localparam [5:0] LINE_COL = 6'b11_11_11;
    localparam [5:0] TARMAC0  = 6'b01_01_01;
    localparam [5:0] TARMAC1  = 6'b10_10_10;
    localparam [5:0] KERB0    = 6'b11_11_11;
    localparam [5:0] KERB1    = 6'b11_00_00;
    localparam [5:0] GRASS0   = 6'b00_10_00;
    localparam [5:0] GRASS1   = 6'b01_10_00;
    localparam [5:0] WHEEL0   = 6'b00_00_00;
    localparam [5:0] WHEEL1   = 6'b10_10_10;

    // ---- regions, as bit slices of y (y < 480)
    // Stage 2 works on the pixel one clock earlier, so it can use a local copy
    // of y. That takes most of the load off the y counter.
    // The wheel and the digits never touch column 0, so they can use a copy too.
    // y_w is stored inverted, or synthesis would merge the two copies into one.
    reg [9:0] y_q, y_wn;
    wire [9:0] y_w = ~y_wn;
    always @(posedge clk) begin
        y_q  <= y;
        y_wn <= ~y;
    end
    wire sky  = (y_q[9:7] == 3'b000);                 // y < 128
    wire dash = y_q[8] & (y_q[7] | (y_q[6] & y_q[5]));// y >= 352
    wire [7:0] s_y = {~y_q[7], y_q[6:0]};             // y - 128, valid on road rows
    wire [7:0] s_now = {~y[7], y[6:0]};               // the same one clock sooner

    // ---- road geometry for this line (w = s_y)
    wire [8:0] kerb_w = {1'b0, s_y} + {4'b0000, s_y[7:3]};
    wire [3:0] dash_w = {1'b0, s_y[7:5]} + 4'd1;

    wire signed [10:0] dx = $signed({1'b0, x}) + Ae;    // x - centre
    wire        [9:0]  d  = dx[10] ? ~dx[9:0] : dx[9:0]; // |dx|, or |dx| - 1 when negative

    wire [3:0] band   = z[3:0] + d_hi;
    wire       stripe = band[3] & (s_y[7:5] != 3'b000);  // no stripes for s_y < 32

    // ---- mountains: a triangle wave indexed by x + h, so they slide as you turn
    wire [6:0] u      = x[6:0] + h[6:0];
    wire [4:0] tri_w  = u[5] ? ~u[4:0] : u[4:0];
    wire [5:0] mh     = {1'b0, tri_w} + (u[6] ? {2'b00, tri_w[4:1]} : 6'd0);
    wire       peak   = ({1'b0, ~y[6:0]} < {2'b00, mh});  // 127 - y < height

    // ---- traffic. Scanning down, the last row with z >= zc is a car's base. Its Ae and s_y are stored there, and
    // the next frame draws from them, so the car is upright: one width and one
    // position for all its rows. Written only at the base row, so no second copy.
    reg on_slow, on_onc;
    reg signed [10:0] ae_slow, ae_onc;
    reg        [7:0]  s_slow, s_onc;
    wire on_slow_next = (zs >= zc_slow);
    wire on_onc_next  = (zs >= zc_onc);
    reg  base_ok, cap_slow, cap_onc;
    always @(posedge clk) begin
        base_ok  <= (y >= 10'd129) && (y <= 10'd382);   // rows 1..254
        cap_slow <= latch && base_ok && on_slow && !on_slow_next;
        cap_onc  <= latch && base_ok && on_onc  && !on_onc_next;
    end
    always @(posedge clk) begin
        if (!rst_n) begin
            on_slow <= 1'b0;
            on_onc  <= 1'b0;
            s_slow  <= 8'd0;
            s_onc   <= 8'd0;
            ae_slow <= 11'd0;
            ae_onc  <= 11'd0;
        end else begin
            if (latch) begin
                on_slow <= on_slow_next;
                on_onc  <= on_onc_next;
            end
            if (cap_slow) begin
                ae_slow <= Ae;
                s_slow  <= s_y;
            end
            if (cap_onc) begin
                ae_onc <= Ae;
                s_onc  <= s_y;
            end
            if (clr_slow) s_slow <= 8'd0;
            if (clr_onc)  s_onc  <= 8'd0;
        end
    end

    // Each car's column offset from the near edge of its rear face, with one
    // adder: the slow car (right of its reference) is x + Ae - s/4, and the
    // oncoming car is ~(x + Ae + s/4). Both constants change only at the base row.
    reg signed [10:0] k_slow, k_onc;
    always @(posedge clk) begin
        k_slow <= ae_slow - $signed({5'b00000, s_slow[7:2]});
        k_onc  <= ae_onc  + $signed({5'b00000, s_onc[7:2]});
    end
    wire [10:0] u_slow =   $signed({1'b0, x}) + k_slow;
    wire [10:0] u_onc  = ~($signed({1'b0, x}) + k_onc);
    reg  [10:0] u_slow_q, u_onc_q;
    // row tests for the next pixel stage, from y one clock sooner
    reg rows_slow_q, rows_onc_q;
    reg [7:0] col_b_q;
    wire [8:0] top_slow = {2'b00, s_slow[7:1]} + {4'b0000, s_slow[7:3]};
    wire [8:0] top_onc  = {2'b00, s_onc[7:1]}  + {4'b0000, s_onc[7:3]};
    always @(posedge clk) begin
        rows_slow_q <= ({1'b0, s_now} >= top_slow) && (s_now <= s_slow);
        rows_onc_q  <= ({1'b0, s_now} >= top_onc)  && (s_now <= s_onc);
        col_b_q     <= {1'b0, s_now[7:1]} + {2'b00, s_now[7:2]};
    end

    wire [7:0] col_a  = {2'b00, s_y[7:2]};

    // ---- score, on the dashboard
    wire [1:0] score_code;
    score_display score (.clk(clk), .v(v), .x(x), .y(y_w), .tens(tens), .ones(ones), .code(score_code));

    // ---- static interior
    wire [2:0] inner_code;
    interior cockpit (.x(x), .y(y), .code(inner_code));

    // ---- steering wheel, drawn over everything else
    // The angle comes from far across the chip and only changes in vertical
    // blanking, so a local copy takes that distance off the per-pixel path.
    reg signed [2:0] angle;
    always @(posedge clk)
        angle <= wheel;
    wire [1:0] wheel_code;
    steering_wheel #(.FULL(WHEEL_FULL)) steer (
        .clk(clk), .x(x), .y(y_w), .w(angle), .code(wheel_code)
    );

    // ---- stage 1 registers. Everything else used below depends only on y,
    // or changes only during blanking, so it is the same for the pixel one
    // clock earlier (at a line change that pixel is in blanking anyway).
    reg [9:0] d_q;
    reg [1:0] wheel_q;
    reg [2:0] inner_q;
    reg [1:0] score_q;
    reg       left_q;
    reg       peak_q, active_q, dither_q;
    always @(posedge clk) begin
        d_q      <= d;
        left_q   <= dx[10];
        u_slow_q   <= u_slow;
        u_onc_q    <= u_onc;
        score_q  <= score_code;
        inner_q  <= inner_code;
        wheel_q  <= WHEEL_FULL ? wheel_code : {1'b0, wheel_code[0]};
        peak_q   <= peak;
        dither_q <= y[4] & (x[0] ^ y[0]);       // checkerboard in each band's lower half
        active_q <= active;
    end

    // ---- stage 2
    // when the road curves, its last rows are grass: it bends out of sight
    reg curved;
    always @(posedge clk)
        curved <= (kappa[2:0] ^ {3{kappa[3]}}) != 3'd0;
    wire near_horizon = (s_y[7:4] == 4'd0) & (~s_y[3] | (s_y[2:0] == 3'd0));
    wire [1:0] slow_kind;       // 0 none, 1 body, 3 lamp
    wire [1:0] onc_kind;
    wire       slow_side, onc_side;
    car_shape shape_slow (.s(s_slow), .rows(rows_slow_q), .u(u_slow_q),
                          .road_side(~left_q), .d(d_q), .col_a(col_a), .col_b(col_b_q),
                          .kind(slow_kind), .side(slow_side));
    car_shape shape_onc  (.s(s_onc), .rows(rows_onc_q), .u(u_onc_q),
                          .road_side(left_q), .d(d_q), .col_a(col_a), .col_b(col_b_q),
                          .kind(onc_kind), .side(onc_side));
    always @(*) begin
        if (!active_q)
            rgb = 6'b00_00_00;
        else if (wheel_q != 2'd0)
            rgb = (wheel_q == 2'd1) ? WHEEL0 : (wheel_q == 2'd2) ? BAR_COL : WHEEL1;
        else if (score_q == 2'd2)
            rgb = BAR_COL;
        else if (score_q == 2'd1)
            rgb = PANEL_COL;
        else if (inner_q == 3'd1 || inner_q == 3'd3)
            rgb = COCKPIT;
        else if (inner_q == 3'd2)
            rgb = MIRROR;
        else if (inner_q == 3'd5)
            rgb = VENT_COL;
        else if (sky)
            rgb = peak_q ? MOUNTAIN :
                  (y_q[6:5] == 2'd0) ? (dither_q ? SKY1 : SKY0) :
                  (y_q[6:5] == 2'd1) ? (dither_q ? SKY2 : SKY1) :
                  (y_q[6:5] == 2'd2) ? (dither_q ? SKY3 : SKY2) :
                                       (dither_q ? SKY4 : SKY3);
        else if (dash)
            rgb = DASH_COL;
        else if ((s_y == 8'd0) || (near_horizon && curved))
            rgb = GRASS0;
        else if (onc_kind != 2'd0)
            rgb = onc_kind[1] ? ONC_LAMP : ONC_BODY;
        else if (onc_side)
            rgb = ONC_SIDE;
        else if (slow_kind != 2'd0)
            rgb = slow_kind[1] ? SLOW_LAMP : SLOW_BODY;
        else if (slow_side)
            rgb = SLOW_SIDE;
        else if (stripe && d_q < {6'd0, dash_w})
            rgb = LINE_COL;
        else if (d_q < {2'b00, s_y})
            rgb = stripe ? TARMAC1 : TARMAC0;
        else if (d_q < {1'b0, kerb_w})
            rgb = stripe ? KERB1 : KERB0;
        else
            rgb = stripe ? GRASS1 : GRASS0;

        // side window: the world, with each colour channel halved
        if (inner_q == 3'd6 && active_q)
            rgb = {1'b0, rgb[5], 1'b0, rgb[3], 1'b0, rgb[1]};
        if (flash && active_q)
            rgb[5:4] = 2'b11;
    end
    wire _unused = &{h[7], band[2:0], 1'b0};
endmodule

// ==========================================================================
// steering_wheel.v
// ==========================================================================
// Steering wheel in the foreground, centred on column 320, row 448 (the screen
// cuts off its lower part). Purely combinational: its result is registered as
// part of stage 1 of pixel_colour.
//
// The wheel angle w has five values, so there is no trigonometry:
//   rim    two octagons, inside when a < R, b < R and a + b < sqrt(2) R,
//          where a = |dx| and b = |dy| use bit inversion, not negation
//   spoke  sheared by slope w/4 (a shift): the top bits of dy - w dx / 4 agree
//
// The centre and radius make dx and dy bit slices of the counters.
// FULL = 0: for a 1x1 tile. Radius 64, 8 px rim, one spoke, one colour.
// FULL = 1: for a 1x2 tile. Radius 128, 16 px rim, T of spokes, marker, hub.
// code: 0 no wheel here, 1 black, 2 yellow, 3 grey.

module steering_wheel #(parameter FULL = 0) (
    input  wire       clk,
    input  wire [9:0] x,
    input  wire [9:0] y,
    input  wire signed [2:0] w,
    output wire [1:0] code
);
    wire tilted   = (w[1:0] != 2'b00);
    wire positive = ~w[2] & tilted;
    wire negative =  w[2];

    generate if (FULL) begin : g_full
        // Two clocks: the adders here, the compares after the registers. Its
        // result is one clock later than the other per-pixel logic, which moves
        // the wheel one pixel to the right.
        wire on = (x >= 10'd192) & (x < 10'd448) & y[8] & (y[7] | y[6]);
        wire [7:0] dx = {~(x[7] ^ x[6]), ~x[6], x[5:0]};    // -128..127
        wire [7:0] dy = {y[7] ^ y[6],    ~y[6], y[5:0]};    // -128..31
        wire [6:0] a  = dx[6:0] ^ {7{dx[7]}};
        wire [6:0] b  = dy[6:0] ^ {7{dy[7]}};
        wire [7:0] s  = a + b;

        // marker on the top of the rim, 16 px wide, centred on dx = 16 w
        wire [4:0] m       = dx[7:3] - {w[2], w, 1'b0};
        wire       mark_at = dy[7] & ((m == 5'd0) | (m == 5'b11111));

        // shifts: |w| = 1 is >> 2, |w| = 2 is >> 1
        wire [7:0] tx = !tilted ? 8'd0 : w[0] ? {{2{dx[7]}}, dx[7:2]} : {dx[7], dx[7:1]};
        wire [7:0] ty = !tilted ? 8'd0 : w[0] ? {{2{dy[7]}}, dy[7:2]} : {dy[7], dy[7:1]};
        wire [7:0] sh = dy + (tx ^ {8{positive}});          // across spoke
        wire [7:0] sv = dx + (ty ^ {8{negative}});          // lower spoke

        reg [6:0] a_q;
        reg [7:0] s_q;
        reg [4:0] sh_q, sv_q;
        reg       on_q, mark_q;
        always @(posedge clk) begin
            a_q     <= a;
            s_q     <= s;
            on_q    <= on;
            mark_q  <= mark_at;
            sh_q    <= sh[7:3];
            sv_q    <= sv[7:3];
        end

        wire sp_h = (sh_q == 5'd0) | (sh_q == 5'b11111);
        wire sp_v = ((sv_q == 5'd0) | (sv_q == 5'b11111)) & ~dy[7];
        wire spoke_q = sp_h | sp_v;

        // a, b < 128 from their widths
        wire in_out = (s_q < 8'd181);
        wire in_in  = (a_q < 7'd112) & (b < 7'd112) & (s_q < 8'd158);
        wire rim    = in_out & ~in_in;
        wire hub    = (a_q < 7'd20) & (b < 7'd20) & (s_q < 8'd28);

        assign code = !on_q        ? 2'd0 :
                      rim & mark_q ? 2'd2 :
                      rim          ? 2'd1 :
                      hub          ? 2'd2 :
                      in_in & spoke_q ? 2'd3 : 2'd0;
    end else begin : g_small
        wire on = (x[9:7] == 3'b010) & y[8] & y[7];
        wire [6:0] dx = {~x[6], x[5:0]};                    // -64..63
        wire [6:0] dy = {~y[6], y[5:0]};
        wire [5:0] a  = dx[5:0] ^ {6{dx[6]}};
        wire [5:0] b  = dy[5:0] ^ {6{dy[6]}};
        wire [6:0] s  = a + b;

        wire in_in = (a < 6'd56) & (b < 6'd56) & (s < 7'd80);
        wire rim   = (s < 7'd92) & ~in_in;                  // a, b < 64 from `on`

        wire [6:0] t  = !tilted ? 7'd0 : w[0] ? {{2{dx[6]}}, dx[6:2]} : {dx[6], dx[6:1]};
        wire [6:0] sh = dy + (t ^ {7{positive}});
        wire spoke = in_in & ((sh[6:2] == 5'd0) | (sh[6:2] == 5'b11111));

        assign code = {1'b0, on & (rim | spoke)};
    end endgenerate

    wire _unused = &{negative, 1'b0};
endmodule

// ==========================================================================
// interior.v
// ==========================================================================
// The static inside of the car, tested per pixel from the screen counters.
// We sit on the left, so only the left has a pillar. The pillar's edge moves
// away from the centre going up: t = y/4 + ~x is -32..-1 on the pillar and
// >= 0 on the side window beyond it, which needs one adder and no carry in.
// code: 0 none, 1 roof or pillar, 2 mirror, 3 top of the dashboard,
//       5 vent slat, 6 side window.

module interior (
    input  wire [9:0] x,
    input  wire [9:0] y,
    output wire [2:0] code
);
    wire [10:0] t = {4'b0000, y[8:2]} + ~{1'b0, x};
    wire dash   = y[8] & (y[7] | (y[6] & y[5]));            // y >= 352
    wire roof   = (y[9:4] == 6'd0);                         // y < 16
    wire pillar = ~dash & (t[10:5] == 6'b111111);
    wire window = ~dash & ~roof & ~t[10];
    wire mirror = (x[9:7] == 3'b010) & (y[9:4] == 6'd1);    // rows 16-31
    wire pad    = (y[8:4] == 5'b10110);                     // rows 352-367
    wire vent   = (y[8:5] == 4'b1101) & (x[9:6] == 4'b1001) & (x[5:4] != 2'b11) & y[2];

    assign code = mirror        ? 3'd2 :
                  roof | pillar ? 3'd1 :
                  pad           ? 3'd3 :
                  vent          ? 3'd5 :
                  window        ? 3'd6 : 3'd0;
endmodule

// ==========================================================================
// score_display.v
// ==========================================================================
// Two pairs of seven-segment digits on the dashboard, rows 384-447: the score at
// columns 512-575 and the speed (v / 2, 0..96) at columns 64-127. One decoder
// serves all four digits, since only one is being scanned at a time. Each digit is a 32 x 64 cell of 4 x 8 pixel blocks, cx 0-7 and cy 0-7.
// code: 0 none, 1 panel, 2 lit segment.

module score_display (
    input  wire       clk,
    input  wire [7:0] v,
    input  wire [9:0] x,
    input  wire [9:0] y,
    input  wire [3:0] tens,
    input  wire [3:0] ones,
    output wire [1:0] code
);
    // speed in BCD by shift-and-add-3, registered: v only changes once a frame
    reg [7:0] bcd, speed;
    integer i;
    always @(*) begin
        bcd = 8'd0;
        for (i = 7; i >= 1; i = i - 1) begin
            if (bcd[3:0] >= 4'd5) bcd[3:0] = bcd[3:0] + 4'd3;
            if (bcd[7:4] >= 4'd5) bcd[7:4] = bcd[7:4] + 4'd3;
            bcd = {bcd[6:0], v[i]};
        end
    end
    always @(posedge clk)
        speed <= bcd;

    wire       right = (x[9:6] == 4'b1000);
    wire       left  = (x[9:6] == 4'b0001);
    wire       panel = (right | left) & (y[8:6] == 3'b110);
    wire [2:0] cx    = x[4:2];
    wire [2:0] cy    = y[5:3];
    wire [3:0] digit = right ? (x[5] ? ones : tens) : (x[5] ? speed[3:0] : speed[7:4]);

    reg [6:0] seg;                                          // gfedcba
    always @(*) begin
        case (digit)
            4'd0:    seg = 7'b0111111;
            4'd1:    seg = 7'b0000110;
            4'd2:    seg = 7'b1011011;
            4'd3:    seg = 7'b1001111;
            4'd4:    seg = 7'b1100110;
            4'd5:    seg = 7'b1101101;
            4'd6:    seg = 7'b1111101;
            4'd7:    seg = 7'b0000111;
            4'd8:    seg = 7'b1111111;
            default: seg = 7'b1101111;
        endcase
    end

    wire mid   = (cx >= 3'd1) & (cx <= 3'd5);
    wire upper = (cy >= 3'd1) & (cy <= 3'd3);
    wire lower = (cy >= 3'd5) & (cy <= 3'd6);
    wire lit = (seg[0] & mid & (cy == 3'd0)) | (seg[1] & (cx == 3'd6) & upper) |
               (seg[2] & (cx == 3'd6) & lower) | (seg[3] & mid & (cy == 3'd7)) |
               (seg[4] & (cx == 3'd0) & lower) | (seg[5] & (cx == 3'd0) & upper) |
               (seg[6] & mid & (cy == 3'd4));

    assign code = !panel ? 2'd0 : lit ? 2'd2 : 2'd1;
    wire _unused = &{v[0], 1'b0};
endmodule

// ==========================================================================
// car_shape.v
// ==========================================================================
// The shape of one upright car in the current row and column: a cuboid. s is
// the car's base row; its rear face is s/2 wide and 3s/8 tall, with lamps at
// the outer eighths. The side panel lies just beyond the rear face and stops at
// the road's ground line for this row, so it vanishes when the car is straight
// ahead. Purely combinational, in stage 2 of pixel_colour.

module car_shape (
    input  wire [7:0] s,
    input  wire       rows,      // this row is inside the car, registered
    input  wire [10:0] u,        // columns from the rear face's near edge, registered
    input  wire       road_side, // on this car's side of the road centre
    input  wire [9:0] d,         // |x - road centre| for this row
    input  wire [7:0] col_a,     // s_y / 4
    input  wire [7:0] col_b,     // 3 s_y / 4, registered
    output wire [1:0] kind,      // 0 none, 1 body, 3 lamp
    output wire       side
);
    wire [7:0] half  = {1'b0, s[7:1]};
    wire [7:0] w     = {3'b000, s[7:3]};
    wire [7:0] h_w   = half - w;
    wire [8:0] h_p   = {1'b0, half} + {1'b0, w};

    // everything is measured from the rear face's near edge
    wire        neg  = u[10];
    wire        near = (u[10:8] == 3'b000);      // 0 .. 255
    wire [7:0]  ul   = u[7:0];

    wire lt_half = near & (ul < half);
    wire lamp    = (ul < w) | (ul >= h_w);

    assign kind = {rows & lt_half & lamp, rows & lt_half};

    wire inner = neg & (u[9:8] == 2'b11) & (~ul < w) & (d >= {2'b00, col_a});
    wire outer = near & ~lt_half & ({1'b0, ul} < h_p) & (d < {2'b00, col_b});
    assign side = rows & road_side & (inner | outer);
endmodule

// ==========================================================================
// engine_audio.v
// ==========================================================================
// Engine sound. A phase accumulator steps once per line (31.25 kHz) with a step
// that rises with speed: inc = 128 + 2v gives about 61 Hz idling, 244 Hz at top
// speed. 128 + 2v = (v + 64) << 1, so it needs only a 2-bit increment. The sample is a sawtooth plus a square an octave below. Off the road,
// LFSR noise is mixed in for a gravel rumble. The output pin is PWM: high
// while the low 8 bits of the VGA x counter are below the sample, which gives
// a 98 kHz carrier with no counter of its own.

module engine_audio (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       tick,       // once per line
    input  wire [7:0] v,
    input  wire       offroad,
    input  wire [7:0] pwm_count,  // x[7:0] from the VGA timing
    output wire [7:0] sample,
    output reg        out
);
    reg [16:0] phase;
    reg [14:0] lfsr;

    wire [8:0] v64 = {1'b0, v} + 9'd64;
    wire [9:0] inc = {v64, 1'b0};

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= 17'd0;
            lfsr  <= 15'h7FFF;
        end else if (tick) begin
            phase <= phase + {7'd0, inc};
            lfsr  <= {lfsr[13:0], lfsr[14] ^ lfsr[13]};
        end
    end

    wire [7:0] base = {1'b0, phase[15:9]} + (phase[16] ? 8'd64 : 8'd0);
    assign sample = offroad ? (base ^ {2'b00, lfsr[5:0]}) : base;

    // registered, so the pin is driven straight from a flip-flop
    always @(posedge clk)
        out <= (pwm_count < sample);
endmodule
